1	import type { DurableIssuancePruningReceipt } from "@ts-drp/issuance-store/maintenance";
2	import type { AheReclamationReceipt } from "@ts-drp/storage/maintenance";
3	
4	const INPUT_KEYS = Object.freeze(["aheReceipt", "issuanceReceipt", "successor"] as const);
5	
6	export const D109D_RUNTIME_RECLAMATION_ERROR_CODES = Object.freeze([
7		"D109D_INVALID_ARGUMENT",
8		"D109D_RECEIPT_MISMATCH",
9		"D109D_IDENTITY_MISMATCH",
10		"D109D_RUNTIME_NOT_READY",
11		"D109D_INTERNAL_INVARIANT",
12	] as const);
13	
14	export type D109dRuntimeReclamationErrorCode = (typeof D109D_RUNTIME_RECLAMATION_ERROR_CODES)[number];
15	
16	export type D109dRuntimeCensus = Readonly<{
17		applicationAuthors: number;
18		applicationCharges: number;
19		applicationVertices: number;
20		blueprintState: boolean;
21		causalityIndex: number;
22		creatorCloseDerivedCommitment: boolean;
23		creatorCloseDurableReplay: boolean;
24		creatorCloseGraph: boolean;
25		creatorClosePersistedSnapshot: boolean;
26		creatorCloseStagedSnapshot: boolean;
27		displacedRebaseCursor: boolean;
28		displacedSource: boolean;
29		epochBytes: number;
30		graphVersion: number;
31		hotPredecessor: boolean;
32		latchedOperations: number;
33		pendingIngress: number;
34		pendingIngressBytes: number;
35		publication: boolean;
36		quarantine: number;
37		rebase: boolean;
38		retainedPayloadMetadata: boolean;
39	}>;
40	
41	export type D109dRuntimeReclamationResult =
42		| Readonly<{
43				after: D109dRuntimeCensus;
44				before: D109dRuntimeCensus;
45				closedEpoch: number;
46				objectId: string;
47				ok: true;
48				replay: boolean;
49				successorEpoch: number;
50		  }>
51		| Readonly<{ readonly code: D109dRuntimeReclamationErrorCode; readonly ok: false }>;
52	
53	export type D109dRuntimeReclamationInput = Readonly<{
54		readonly aheReceipt: AheReclamationReceipt;
55		readonly issuanceReceipt: DurableIssuancePruningReceipt;
56		readonly successor: object;
57	}>;
58	
59	export type CreatorCloseRuntimeReleaseCensus = Readonly<{
60		readonly derivedCommitment: boolean;
61		readonly durableReplay: boolean;
62		readonly graph: boolean;
63		readonly persistedSnapshot: boolean;
64		readonly stagedSnapshot: boolean;
65	}>;
66	
67	export type CreatorCloseRuntimeReleasePlan = Readonly<{
68		readonly after: CreatorCloseRuntimeReleaseCensus;
69		readonly before: CreatorCloseRuntimeReleaseCensus;
70		release(): boolean;
71	}>;
72	
73	type RuntimeReclamationKernel = (input: D109dRuntimeReclamationInput) => Promise<D109dRuntimeReclamationResult>;
74	type CreatorCloseRuntimeReleaseOwner = (plane: object) => CreatorCloseRuntimeReleasePlan | undefined;
75	
76	let runtimeKernel: RuntimeReclamationKernel | undefined;
77	let creatorCloseReleaseOwner: CreatorCloseRuntimeReleaseOwner | undefined;
78	
79	function invalid(): D109dRuntimeReclamationResult {
80		return Object.freeze({ code: "D109D_INVALID_ARGUMENT" as const, ok: false as const });
81	}
82	
83	function captureInput(value: unknown): D109dRuntimeReclamationInput | undefined {
84		try {
85			if (value === null || typeof value !== "object" || Object.getPrototypeOf(value) !== Object.prototype) {
86				return undefined;
87			}
88			const keys = Reflect.ownKeys(value);
89			if (
90				keys.length !== INPUT_KEYS.length ||
91				keys.some((key) => typeof key !== "string" || !INPUT_KEYS.includes(key as (typeof INPUT_KEYS)[number]))
92			) {
93				return undefined;
94			}
95			const captured = Object.create(null) as Record<string, unknown>;
96			for (const key of INPUT_KEYS) {
97				const descriptor = Object.getOwnPropertyDescriptor(value, key);
98				if (descriptor === undefined || descriptor.enumerable !== true || !("value" in descriptor)) return undefined;
99				captured[key] = descriptor.value;
100			}
101			if (captured.successor === null || typeof captured.successor !== "object") return undefined;
102			return Object.freeze({
103				aheReceipt: captured.aheReceipt as AheReclamationReceipt,
104				issuanceReceipt: captured.issuanceReceipt as DurableIssuancePruningReceipt,
105				successor: captured.successor,
106			});
107		} catch {
108			return undefined;
109		}
110	}
111	
112	/**
113	 * Installs the sole v3 registration reclamation kernel.
114	 * @param owner - Private runtime owner.
115	 * @returns Whether the first owner was installed.
116	 */
117	export function installV3RuntimeReclamationKernel(owner: RuntimeReclamationKernel): boolean {
118		if (runtimeKernel !== undefined || typeof owner !== "function") return false;
119		runtimeKernel = owner;
120		return true;
121	}
122	
123	/**
124	 * Installs the sole creator-close duplicate-release owner.
125	 * @param owner - Private creator-close owner.
126	 * @returns Whether the first owner was installed.
127	 */
128	export function installCreatorCloseRuntimeRelease(owner: CreatorCloseRuntimeReleaseOwner): boolean {
129		if (creatorCloseReleaseOwner !== undefined || typeof owner !== "function") return false;
130		creatorCloseReleaseOwner = owner;
131		return true;
132	}
133	
134	/**
135	 * Prepares a no-throw creator-close release before runtime mutation starts.
136	 * @param plane - Genuine retired predecessor handle.
137	 * @returns Prepared release and exact before/after census when ready.
138	 */
139	export function prepareCreatorCloseRuntimeRelease(plane: object): CreatorCloseRuntimeReleasePlan | undefined {
140		try {
141			return creatorCloseReleaseOwner?.(plane);
142		} catch {
143			return undefined;
144		}
145	}
146	
147	/**
148	 * Releases receipt-covered installed-v3 predecessor retention.
149	 * @param value - Exact receipt pair and genuine current successor handle.
150	 * @returns Frozen success census or a closed fail-closed refusal.
151	 */
152	export function reclaimInstalledV3Runtime(value: unknown): Promise<D109dRuntimeReclamationResult> {
153		const input = captureInput(value);
154		if (input === undefined) return Promise.resolve(invalid());
155		if (runtimeKernel === undefined) {
156			return Promise.resolve(Object.freeze({ code: "D109D_INTERNAL_INVARIANT" as const, ok: false as const }));
157		}
158		try {
159			return Promise.resolve(runtimeKernel(input)).catch(() =>
160				Object.freeze({ code: "D109D_INTERNAL_INVARIANT" as const, ok: false as const })
161			);
162		} catch {
163			return Promise.resolve(Object.freeze({ code: "D109D_INTERNAL_INVARIANT" as const, ok: false as const }));
164		}
165	}

